    self: &Arc<Self>,
    Tracked(oneshot0_complete): Tracked<OneShotResource>,
    Tracked(oneshot1_complete): Tracked<OneShotResource>,
) -> (x: u32)
    requires
        self.wf(),
        oneshot0_complete.id() == self.get_oneshot_id(0),
        oneshot1_complete.id() == self.get_oneshot_id(1),
        oneshot0_complete@ is Complete,
        oneshot1_complete@ is Complete,
    ensures
        x == 2,
{
    let x_value: u32;
    open_atomic_invariant!(self.inv.borrow() => inner => {
        proof {
            // From the invariant predicate, we know that for each one-shot:
            // Either it's HalfRightToComplete or Complete
            // 
            // Since we have complete resources outside the invariant with the same IDs,
            // and resources at the same location compose according to the resource algebra,
            // the only way for this to be consistent is if the resources inside are also complete.
            //
            // Specifically, looking at the one-shot resource algebra:
            // - Complete OP Complete = Complete
            // - Complete OP HalfRightToComplete = Invalid  
            // - Complete OP Empty = Complete
            //
            // So if we have a Complete resource outside, the resource inside must be
            // either Complete or Empty for the composition to be valid.
            // But since we know from the invariant that the inside resource is
            // either HalfRightToComplete or Complete, and we can't have a composition
            // that results in Complete if one is Complete and the other is HalfRightToComplete
            // (that would be Invalid), the internal resources must also be Complete.

            // Establish that the internal resources are complete
            assert(inner.oneshot0_inv_half@ is Complete);
            assert(inner.oneshot1_inv_half@ is Complete);

            // Given that both are complete, the invariant formula gives us:
            assert(inner.x_perm@.value == (if inner.oneshot0_inv_half@ is Complete { 1int } else { 0int }) + (if inner.oneshot1_inv_half@ is Complete { 1int } else { 0int }));
