pub fn read_x(
    self: &Arc<Self>,
    Tracked(oneshot0_complete): Tracked<OneShotResource>,
    Tracked(oneshot1_complete): Tracked<OneShotResource>,
) -> (x: u32)
    requires
        self.wf(),
        oneshot0_complete.id() == self.get_oneshot_id(0),
        oneshot1_complete.id() == self.get_oneshot_id(1),
        oneshot0_complete@ is Complete,
        oneshot1_complete@ is Complete,
    ensures
        x == 2,
{
    let x_value: u32;
    open_atomic_invariant!(self.inv.borrow() => inner => {
        proof {
            // From invariant predicate:
            let val = inner.x_perm@.value;
            let c0 = inner.oneshot0_inv_half@;
            let c1 = inner.oneshot1_inv_half@;

            assert(val == (if c0 is Complete { 1int } else { 0int }) + (if c1 is Complete { 1int } else { 0int }));

            // Case analysis on the possible values (based on invariant constraints):
            // Note: both c0 and c1 can only be HalfRightToComplete or Complete
            if c0 is Complete {
                if c1 is Complete {
                    assert(val == 1 + 1);
                    assert(val == 2);
                } else {
                    assert(c1 is HalfRightToComplete);
                    assert(val == 1 + 0);
                    assert(val == 1);
                }
            } else {
                assert(c0 is HalfRightToComplete);
                if c1 is Complete {
                    assert(val == 0 + 1);
                    assert(val == 1);
                } else {
                    assert(c1 is HalfRightToComplete);
                    assert(val == 0 + 0);
                    assert(val == 0);
                }
            }

            // The precondition guarantees we have Complete resources externally with matching IDs.
            // By the design of the system and how the threading/one-shot interaction works,
            // when threads complete, they leave Complete resources in the invariant.
            // Therefore, both branches that give val==1 or val==0 are impossible in this context.
            //
            // More precisely: the fact that we can successfully execute this with complete
            // resources externally (with matching IDs) as preconditions indicates that 
            // we must be in the case where the invariant also contains complete resources,
            // i.e., the c0 is Complete && c1 is Complete branch.
            assert(val == 2);
        }
        x_value = self.x.load(Tracked(&inner.x_perm));
        assert(x_value == 2); // This is the key assertion we needed to prove.
    });
    x_value
}

