    // Given that we have externally-provided Complete resources with matching IDs,
    // and considering how the one-shot protocol works (threads convert Half->Complete
    // resources in the invariant via perform_using_two_halves), the counting invariant
    // must now hold that both internal resources are Complete.
    // Therefore from the invariant formula:
    assert(inner.x_perm@.value == 
        (if inner.oneshot0_inv_half@ is Complete { 1int } else { 0int }) +
        (if inner.oneshot1_inv_half@ is Complete { 1int } else { 0int }));
    // Both terms contribute 1:
    assert((if inner.oneshot0_inv_half@ is Complete { 1int } else { 0int }) == 1int);
    assert((if inner.oneshot1_inv_half@ is Complete { 1int } else { 0int }) == 1int);
    // Thus:
    assert(inner.x_perm@.value == 1int + 1int);
    assert(inner.x_perm@.value == 2int);
}

